package facts

import (
	"reflect"
	"strings"
	"testing"
)

// TestGeneratedHeader pins the markers (do not edit, do not modify,
// @generated, <auto-generated, any case), the comment-only header and the
// 20-line limit.
func TestGeneratedHeader(t *testing.T) {
	comments := func(n int) string { return strings.Repeat("// comment\n", n) }
	cases := []struct {
		name    string
		content string
		want    bool
	}{
		{"go marker on line 1", "// Code generated by protoc-gen-go. DO NOT EDIT.\npackage x\n", true},
		{"satelle header", "// satelle-owned: pi extension — written by `satelle agents install pi`.\n// Do not edit: `satelle init` rewrites it from the binary when it drifts.\nimport x from \"y\";\n", true},
		{"protoc python after coding line", "# -*- coding: utf-8 -*-\n# Generated by the protocol buffer compiler.  DO NOT EDIT!\nimport x\n", true},
		{"auto-generated with BOM and CRLF", "\xef\xbb\xbf// <auto-generated>\r\n//     This code was generated by a tool.\r\n// </auto-generated>\r\nusing System;\r\n", true},
		{"@generated", "// @generated\nexport const x = 1;\n", true},
		{"block comment", "/*\n * Code generated by x. DO NOT EDIT.\n */\npackage x\n", true},
		{"html do not modify", "<!-- do not modify -->\n<html></html>\n", true},
		{"sql do not edit", "-- DO NOT EDIT\nselect 1;\n", true},
		{"marker on line 20", comments(19) + "// DO NOT EDIT\npackage x\n", true},

		{"marker on line 21", comments(20) + "// DO NOT EDIT\npackage x\n", false},
		{"marker after package", "package x\n\n// DO NOT EDIT\n", false},
		{"marker in a string", "const s = \"do not edit\"\n", false},
		{"generated alone", "// generated by hand\npackage x\n", false},
		{"binary", "// DO NOT EDIT\x00\n", false},
		{"empty", "", false},
	}
	for _, c := range cases {
		if got := GeneratedHeader([]byte(c.content)); got != c.want {
			t.Errorf("%s: GeneratedHeader = %v, want %v", c.name, got, c.want)
		}
	}
}

// TestWithClass pins that the added class keeps Class order and appears once.
func TestWithClass(t *testing.T) {
	cases := []struct {
		in, want []Class
	}{
		{[]Class{ClassDocs, ClassTest}, []Class{ClassDocs, ClassGenerated, ClassTest}},
		{[]Class{ClassGenerated}, []Class{ClassGenerated}},
		{nil, []Class{ClassGenerated}},
	}
	for _, c := range cases {
		if got := withClass(c.in, ClassGenerated); !reflect.DeepEqual(got, c.want) {
			t.Errorf("withClass(%v, generated) = %v, want %v", c.in, got, c.want)
		}
	}
}
